"""
VIGESORA — AI-Assisted Viral Genomic Surveillance and Outbreak Risk Assessment
Streamlit frontend prototype (version 4: contrast-based font colours).

Run:
    pip install streamlit requests pandas reportlab
    streamlit run vigesora_app.py

Backend integration:
    Set VIGESORA_API_URL=http://localhost:5000/predict
    Then set the analysis mode to "Live Flask API".

Expected POST /predict: multipart/form-data with file=<uploaded FASTA>
Expected JSON: see normalise_result() — optional fields may be missing.

IMPORTANT:
- Demo mode results are explicitly labelled illustrative and are not biological findings.
- No outbreak prediction is claimed.
"""

import json
import os
import re
import time
from datetime import datetime
from html import escape
from io import BytesIO
from typing import Any

import pandas as pd
import streamlit as st

try:
    from reportlab.lib import colors
    from reportlab.lib.enums import TA_LEFT
    from reportlab.lib.pagesizes import A4
    from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
    from reportlab.lib.units import mm
    from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, KeepTogether
    REPORTLAB_AVAILABLE = True
except ImportError:
    REPORTLAB_AVAILABLE = False

# Embedded VIGESORA logo; no separate image file is required at runtime.
VIGESORA_LOGO_DATA_URI = 'data:image/png;base64,'

try:
    import requests
except ImportError:
    requests = None


# ---------------------------------------------------------------------------
# Page setup and visual system
# ---------------------------------------------------------------------------
st.set_page_config(
    page_title="VIGESORA | Viral Genomic Surveillance",
    page_icon="🧬",
    layout="wide",
    initial_sidebar_state="expanded",
)

# Streamlit >= 1.50 uses width="stretch"; older versions use use_container_width.
try:
    _v = tuple(int(x) for x in re.findall(r"\d+", st.__version__)[:2])
except Exception:
    _v = (0, 0)
STRETCH = {"width": "stretch"} if _v >= (1, 50) else {"use_container_width": True}

