@st.cache_data(show_spinner=False)
def parse_fasta(file_bytes: bytes):
    """Basic FASTA structure validation and sequence summary (cached per file)."""
    text = file_bytes.decode("utf-8", errors="replace")
    lines = [line.strip() for line in text.splitlines() if line.strip()]
    headers = [line for line in lines if line.startswith(">")]
    seq = "".join(line for line in lines if not line.startswith(">")).upper()
    allowed = set("ACGTUNRYKMSWBDHV-.")
    invalid = sorted(set(seq) - allowed)
    if not headers:
        return None, "No FASTA header found. Each sequence must begin with a line starting with '>'."
    if len(headers) > 1:
        return None, f"This file contains {len(headers)} sequences. Upload one genome per file."
    if not seq:
        return None, "No sequence data found in the file."
    if invalid:
        return None, "Unexpected sequence character(s): " + ", ".join(invalid[:20])
    if len(seq) < 100:
        return None, "The sequence is very short for a whole-genome SARS-CoV-2 analysis. Upload a suitable genome sequence."
    ambiguous = sum(1 for base in seq if base not in "ACGT")
    return {
        "headers": headers,
        "sequence": seq,
        "genome_length": len(seq),
        "ambiguous_bases": ambiguous,
        "n_count": seq.count("N"),
        "ambiguous_percentage": (ambiguous / len(seq)) * 100,
        "n_percentage": (seq.count("N") / len(seq)) * 100,
        "gc_percentage": ((seq.count("G") + seq.count("C")) / len(seq)) * 100,
    }, None


def make_demo_result(summary: dict[str, Any], filename: str):
    """Demo values are conspicuously labelled and must never be treated as real findings."""
    note = "Illustrative demo row — not computed from this sequence"
    return {
        "status": "success",
        "demo_mode": True,
        "variant": "Omicron (illustrative demo)",
        "confidence": 0.924,
        "genome_length": summary["genome_length"],
        "n_percentage": round(summary["n_percentage"], 3),
        "ambiguous_percentage": round(summary["ambiguous_percentage"], 3),
        "ambiguous_bases": summary["ambiguous_bases"],
        "class_scores": [{"class": "Omicron", "score": 92.4}, {"class": "Alpha", "score": 3.1}, {"class": "Beta", "score": 2.5}, {"class": "Gamma", "score": 2.0}],
        "quality": {"ambiguous_bases": summary["ambiguous_bases"], "ambiguous_percentage": round(summary["ambiguous_percentage"], 3)},
        "evidence": [],
        "warnings": ["DEMO MODE: predicted class and model score are simulated placeholders, not scientific results."],
        "filename": filename,
    }


def call_backend(file_name: str, file_bytes: bytes, api_url: str, timeout_seconds: int = 120):
    if requests is None:
        raise RuntimeError("The 'requests' package is missing. Install it with: pip install requests")
    try:
        response = requests.post(
            api_url,
            files={"file": (file_name, file_bytes, "application/octet-stream")},
            timeout=timeout_seconds,
        )
    except requests.RequestException as exc:
        raise RuntimeError(f"Could not connect to the Flask API at {api_url}. Check that the backend is running. Details: {exc}") from exc
    try:
        payload = response.json()
    except ValueError as exc:
        raise RuntimeError(f"The backend returned a non-JSON response (HTTP {response.status_code}).") from exc
    if not isinstance(payload, dict):
        raise RuntimeError("Backend response must be a JSON object.")
    if not response.ok:
        message = payload.get("message") or payload.get("error") or f"Backend returned HTTP {response.status_code}."
        raise RuntimeError(str(message))
    if payload.get("status", "success") not in ("success", "ok", True):
        raise RuntimeError(str(payload.get("message") or payload.get("error") or "The backend could not analyse this file."))
    return payload


def _to_float(value, fallback):
    try:
        return float(value)
    except (TypeError, ValueError):
        return fallback


def _to_int(value, fallback):
    try:
        return int(value)
    except (TypeError, ValueError):
        return fallback


def normalise_result(payload: dict, summary: dict, filename: str):
    """Normalize the existing API response without inventing unsupported fields."""
    quality = payload.get("quality") or {}
    confidence = payload.get("confidence", payload.get("model_confidence"))
    if confidence is not None:
        confidence = _to_float(confidence, None)
        if confidence is not None and 1 < confidence <= 100:
            confidence /= 100

    raw_scores = payload.get("class_scores") or payload.get("scores") or []
    class_scores = []
    if isinstance(raw_scores, dict):
        raw_scores = [{"class": label, "score": score} for label, score in raw_scores.items()]
    parsed_scores = []
    if isinstance(raw_scores, list):
        for item in raw_scores:
            if isinstance(item, dict):
                label = item.get("class", item.get("label", item.get("variant", "Unknown")))
                score = _to_float(item.get("score", item.get("probability")), None)
                if score is not None:
                    parsed_scores.append((str(label), score))
    # API class_scores are percentages. Some alternate APIs use 0–1 probabilities;
    # normalize only when the complete returned score set clearly uses that scale.
    probability_scale = bool(parsed_scores) and max(score for _, score in parsed_scores) <= 1
    for label, score in parsed_scores:
        if probability_scale:
            score *= 100
        class_scores.append({"class": label, "score": round(score, 2)})

    safe_payload = {key: value for key, value in payload.items() if key not in {"mutation_count", "mutations", "mutation_details"}}
    return {
        **safe_payload,
        "status": "success",
        "demo_mode": bool(payload.get("demo_mode", False)),
        "variant": payload.get("variant", payload.get("predicted_variant", "Not classified")),
        "confidence": confidence,
        "class_scores": class_scores,
        "genome_length": _to_int(payload.get("genome_length", payload.get("sequence_length")), summary["genome_length"]),
        "n_percentage": _to_float(payload.get("n_percentage", quality.get("n_percentage")), summary["n_percentage"]),
        "ambiguous_percentage": _to_float(payload.get("ambiguous_percentage", quality.get("ambiguous_percentage")), summary["ambiguous_percentage"]),
        "ambiguous_bases": payload.get("ambiguous_bases", quality.get("ambiguous_bases", summary["ambiguous_bases"])),
        "gc_percentage": _to_float(quality.get("gc_percentage"), summary.get("gc_percentage")),
        "warnings": payload.get("warnings") or [],
        "evidence": payload.get("evidence") or [],
        "filename": filename,
    }


