def get_variant_information(variant):
    label = str(variant or "").strip().lower()
    for key, info in VARIANT_INFORMATION.items():
        if key in label:
            return info
    return None


def build_pdf_report(report: dict) -> bytes:
    """Build a printable PDF report from the current analysis result."""
    if not REPORTLAB_AVAILABLE:
        raise RuntimeError("PDF export requires ReportLab. Install it with: python -m pip install reportlab")
    output = BytesIO()
    doc = SimpleDocTemplate(output, pagesize=A4, rightMargin=18*mm, leftMargin=18*mm, topMargin=17*mm, bottomMargin=17*mm)
    base = getSampleStyleSheet()
    title_style = ParagraphStyle("VigesoraTitle", parent=base["Title"], textColor=colors.HexColor("#163528"), fontName="Helvetica-Bold", fontSize=20, leading=25, spaceAfter=8)
    h_style = ParagraphStyle("VigesoraH", parent=base["Heading2"], textColor=colors.HexColor("#214A38"), fontSize=12, leading=16, spaceBefore=10, spaceAfter=5)
    body_style = ParagraphStyle("VigesoraBody", parent=base["BodyText"], fontName="Helvetica", fontSize=9, leading=13, spaceAfter=5, wordWrap="CJK")
    small_style = ParagraphStyle("VigesoraSmall", parent=body_style, fontSize=8, textColor=colors.HexColor("#4F5B51"))
    story = [Paragraph("VIGESORA — Variant Classification Report", title_style),
             Paragraph("AI-assisted viral genomic surveillance and variant classification", small_style), Spacer(1, 8)]
    result = report.get("result", {})
    info = report.get("variant_information") or {}
    def para(value):
        return Paragraph(escape(str(value if value is not None else "Not supplied")), body_style)
    story += [Paragraph("Analysis summary", h_style)]
    summary_rows = [
        [para("Uploaded filename"), para(report.get("filename"))],
        [para("Analysis date"), para(report.get("generated_at"))],
        [para("Mode"), para("Illustrative demo — not a scientific result" if report.get("demo_mode") else "Live Flask API")],
        [para("Predicted class"), para(result.get("variant"))],
        [para("Model score"), para(report.get("confidence_display", "Not supplied") + " (not necessarily a calibrated probability)")],
        [para("Sequence length"), para(f'{result.get("genome_length", "Not supplied")} nt')],
        [para("N percentage"), para(f'{result.get("n_percentage", "Not supplied")}%')],
        [para("Ambiguous bases / percentage"), para(f'{result.get("ambiguous_bases", "Not supplied")} / {result.get("ambiguous_percentage", "Not supplied")}%')],
        [para("GC content"), para(f'{result.get("gc_percentage", "Not supplied")}%')],
        [para("Feature coverage"), para(f'{result.get("feature_coverage", "Not supplied")}%')],
    ]
    table = Table(summary_rows, colWidths=[53*mm, 115*mm], repeatRows=0)
    table.setStyle(TableStyle([("BACKGROUND", (0,0), (0,-1), colors.HexColor("#EEF4EE")), ("TEXTCOLOR", (0,0), (-1,-1), colors.HexColor("#202820")), ("GRID", (0,0), (-1,-1), .35, colors.HexColor("#DDE4DC")), ("VALIGN", (0,0), (-1,-1), "TOP"), ("LEFTPADDING", (0,0), (-1,-1), 7), ("RIGHTPADDING", (0,0), (-1,-1), 7), ("TOPPADDING", (0,0), (-1,-1), 6), ("BOTTOMPADDING", (0,0), (-1,-1), 6)]))
    story += [table, Paragraph("Available class scores", h_style)]
    scores = result.get("class_scores") or []
    if scores:
        score_rows = [[para("Class"), para("Score (%)")]] + [[para(x.get("class", "Unknown")), para(x.get("score", "Not supplied"))] for x in scores]
        score_table = Table(score_rows, colWidths=[85*mm, 83*mm], repeatRows=1)
        score_table.setStyle(TableStyle([("BACKGROUND", (0,0), (-1,0), colors.HexColor("#214A38")), ("TEXTCOLOR", (0,0), (-1,0), colors.white), ("GRID", (0,0), (-1,-1), .35, colors.HexColor("#DDE4DC")), ("VALIGN", (0,0), (-1,-1), "TOP"), ("LEFTPADDING", (0,0), (-1,-1), 7), ("TOPPADDING", (0,0), (-1,-1), 5), ("BOTTOMPADDING", (0,0), (-1,-1), 5)]))
        story.append(score_table)
    else:
        story.append(para("The API did not provide scores for every class."))
    if info:
        story += [Paragraph("Variant information", h_style), Paragraph("Historical background", base["Heading3"]), para(info.get("background")), Paragraph("Characteristics", base["Heading3"]), para(info.get("characteristics")), Paragraph("Historical whereabouts", base["Heading3"]), para(info.get("whereabouts"))]
    story.append(Paragraph("Prevention guidance", h_style))
    for item in PREVENTION_GUIDANCE:
        story.append(para("• " + item))
    story += [Paragraph("Treatment and cure information", h_style), para(TREATMENT_GUIDANCE), Paragraph("Model limitations", h_style), para("This experimental model predicts only among the classes represented by its training configuration (Alpha, Beta, Gamma, and Omicron). Its score is not necessarily a calibrated probability and the result is not a formal lineage assignment, clinical diagnosis, or determination of severity, transmissibility, treatment response, or outbreak risk. A single genome does not predict an outbreak."), Paragraph("Warnings", h_style)]
    warnings = result.get("warnings") or []
    if warnings:
        for warning in warnings:
            story.append(para("• " + str(warning)))
    else:
        story.append(para("No additional warnings were supplied by the backend."))
    story += [Paragraph("Trusted references", h_style)]
    for label, url in VARIANT_SOURCES:
        story.append(para(f"{label}: {url}"))
    doc.build(story)
    return output.getvalue()


def render_new_analysis():
    render_header()
    st.markdown(
        '<div class="analysis-intro">'
        '<div class="eyebrow">GENOMIC SANDBOX · RESEARCH WORKSPACE</div>'
        '<h1>New Analysis</h1>'
        '<p>Classify a SARS-CoV-2 genome using the configured VIGESORA model. Upload a FASTA file, review sequence-quality checks, then explore the predicted variant and download a report.</p>'
        '</div>', unsafe_allow_html=True)

    st.markdown('<div class="eyebrow">YOUR WORKFLOW</div>', unsafe_allow_html=True)
    step_cols = st.columns(3)
    step_data = [
        ("1", "Upload a sequence", "Choose one genome in FASTA format."),
        ("2", "Review quality checks", "Check sequence length and ambiguous bases."),
        ("3", "Explore the result", "Review the class scores and export a report."),
    ]
    for col, (number, title, copy) in zip(step_cols, step_data):
        with col:
            st.markdown(f'<div class="analysis-step"><div class="analysis-step-number">{number}</div><div><strong>{title}</strong><span>{copy}</span></div></div>', unsafe_allow_html=True)

    with st.expander("How classification works", expanded=False):
        st.markdown("Upload FASTA → validate basic structure → send the sequence to the configured classifier → review the predicted class and sequence-quality information → download a JSON or PDF report.")
        st.caption("The model only represents Alpha, Beta, Gamma, and Omicron. Its output is experimental and is not a formal lineage assignment or a clinical assessment.")

    st.markdown('<div class="analysis-panel-title">Choose analysis mode</div><div class="analysis-panel-copy">Use the live backend for a real model prediction. Demo mode is only for exploring the interface.</div>', unsafe_allow_html=True)
    mode = st.radio("Analysis mode", ["Demo mode (illustrative results)", "Live Flask API"], horizontal=True, key="analysis_mode", label_visibility="collapsed")
    live = mode == "Live Flask API"
    api_default = os.getenv("VIGESORA_API_URL", "http://localhost:5000/predict")
    if live:
        st.markdown('<div class="analysis-live-note"><strong>Live classification selected.</strong> Predictions will be requested from your Flask API.</div>', unsafe_allow_html=True)
        api_url = st.text_input("Flask API endpoint", value=api_default, help="Expected endpoint: POST /predict with multipart field named 'file'.")
    else:
        api_url = api_default
        st.markdown('<div class="demo-banner"><strong>Demo mode:</strong> classification and model scores are illustrative placeholders. They are not computed from the uploaded genome.</div>', unsafe_allow_html=True)

    st.markdown('<div class="analysis-panel-title">Upload your genome</div><div class="analysis-panel-copy">Supported file extensions: FASTA, FA, FNA, or TXT containing a single FASTA record.</div>', unsafe_allow_html=True)
    uploaded = st.file_uploader("Choose a FASTA file", type=["fasta", "fa", "fna", "txt"], key="fasta_uploader", label_visibility="collapsed", help="Upload one sequence per file. The API expects a single genome.")
    st.markdown('<div class="analysis-upload-note">For best results, use a labelled sequence from a trusted research source. File-format checks do not establish biological validity.</div>', unsafe_allow_html=True)
    if not uploaded:
        st.info("Your sequence summary and analysis controls will appear here after you choose a file.")
    else:
        file_bytes = uploaded.getvalue()
        st.markdown(f'<div class="analysis-live-note"><strong>Selected file:</strong> {escape(uploaded.name)} &nbsp; · &nbsp; {len(file_bytes):,} bytes</div>', unsafe_allow_html=True)
        summary, validation_error = parse_fasta(file_bytes)
        if validation_error:
            st.error(validation_error)
        else:
            st.success("Basic FASTA structure check passed.")
            x1, x2, x3, x4 = st.columns(4)
            x1.metric("Sequence length", f'{summary["genome_length"]:,} nt')
            x2.metric("Ambiguous bases", f'{summary["ambiguous_bases"]:,}')
            x3.metric("N percentage", f'{summary["n_percentage"]:.3f}%')
            x4.metric("GC content", f'{summary["gc_percentage"]:.1f}%')
            st.caption("These checks describe the uploaded sequence; they do not prove biological validity or suitability for the trained model.")

            if st.button("Run variant classification", type="primary", key="analyze_genome", use_container_width=True):
                result, failure = None, None
                progress = st.progress(0, text="Preparing sequence…")
                try:
                    progress.progress(20, text="Checking FASTA structure…")
                    time.sleep(0.15)
                    if live:
                        if not api_url.strip():
                            raise RuntimeError("Enter a Flask API URL.")
                        progress.progress(45, text="Sending FASTA to the backend…")
                        payload = call_backend(uploaded.name, file_bytes, api_url.strip())
                        progress.progress(85, text="Preparing results…")
                        result = normalise_result(payload, summary, uploaded.name)
                    else:
                        progress.progress(55, text="Generating illustrative demo output…")
                        time.sleep(0.2)
                        result = make_demo_result(summary, uploaded.name)
                    progress.progress(100, text="Done")
                except Exception as exc:
                    failure = exc
                if failure:
                    progress.empty()
                    st.error(f"Analysis failed: {failure}")
                    st.info("Check the FASTA file and, in Live Flask API mode, confirm that Flask is running and the endpoint and upload field are correct.")
                else:
                    st.session_state.result = result
                    st.session_state.result_summary = summary
                    add_activity(f"Analysis completed: {uploaded.name} ({'demo' if result.get('demo_mode') else 'API'})")
                    navigate("Analysis Results")

    st.markdown("---")
    if st.button("← Back to Research Overview", key="analysis_back"):
        navigate("Research Overview")

def render_results():
    render_header()
    result = st.session_state.result
    if not result:
        st.markdown('<div class="section"><h1 class="heading">Analysis results</h1><p class="intro">No result is available yet. Start a new analysis first.</p></div>', unsafe_allow_html=True)
        if st.button("Start New Analysis", type="primary"):
            navigate("New Analysis")
        return

    st.markdown('<div class="section"><div class="eyebrow">Genomic Sandbox · Analysis report</div><h1 class="workspace-title">Variant classification results</h1>'
                '<p class="workspace-subtitle">Review the model prediction, class scores, sequence quality, variant background, prevention guidance, and printable reports.</p></div>',
                unsafe_allow_html=True)
    if result.get("demo_mode"):
        st.markdown('<div class="demo-banner"><strong>ILLUSTRATIVE DEMO RESULT.</strong> The predicted class and scores are simulated placeholders—not biological findings. Do not cite them as project results.</div>', unsafe_allow_html=True)
    else:
        st.success("Results received from the configured Flask API. Review warnings and model limitations before interpreting them.")

    variant = result.get("variant", "Not classified")
    confidence = result.get("confidence")
    confidence_label = f"{confidence * 100:.1f}%" if isinstance(confidence, (int, float)) else "Not supplied"
    m1, m2, m3 = st.columns(3)
    m1.metric("Predicted variant", str(variant))
    m2.metric("Model score", confidence_label, help="The score is not necessarily a calibrated probability of biological correctness.")
    m3.metric("Sequence length", f'{_to_int(result.get("genome_length"), 0):,} nt')

    st.markdown("### Sequence quality")
    q1, q2, q3, q4 = st.columns(4)
    q1.metric("N percentage", f'{_to_float(result.get("n_percentage"), 0):.3f}%')
    q2.metric("Ambiguous-base percentage", f'{_to_float(result.get("ambiguous_percentage"), 0):.3f}%')
    q3.metric("Ambiguous bases", str(result.get("ambiguous_bases", "Not supplied")))
    gc_value = result.get("gc_percentage")
    q4.metric("GC content", f"{_to_float(gc_value, 0):.2f}%" if gc_value is not None else "Not supplied")
    coverage = result.get("feature_coverage")
    if coverage is not None:
        st.caption(f"Training-vocabulary feature coverage: {coverage}%")

    scores = result.get("class_scores") or []
    st.markdown("### Scores for supported classes")
    if scores:
        score_frame = pd.DataFrame(scores)
        score_frame = score_frame.rename(columns={"class": "Class", "score": "Model score (%)"})
        st.dataframe(score_frame, hide_index=True, **STRETCH)
    else:
        st.info("The backend did not return class_scores. The current API may return only the top model score; all-class scores will appear when the response includes that field.")

    for warning in result.get("warnings") or []:
        st.warning(str(warning))
    if result.get("error"):
        st.error(str(result["error"]))

    info = get_variant_information(variant)
    st.markdown("### Variant information")
    if info:
        st.markdown(f"#### {info['display']}")
        st.write(info["background"])
        st.markdown("**Characteristics**")
        st.write(info["characteristics"])
        st.markdown("**Historical whereabouts**")
        st.write(info["whereabouts"])
    else:
        st.info("The result does not match one of the four supported class names, so a class-specific information card is not shown.")

    st.markdown("### Prevention guidance")
    for item in PREVENTION_GUIDANCE:
        st.markdown(f"- {item}")
    st.markdown("### Treatment and cure information")
    st.write(TREATMENT_GUIDANCE)
    st.caption("This is general educational information, not individual medical advice. Consult a qualified healthcare professional for diagnosis and treatment.")

    st.markdown("### Trusted references")
    for label, url in VARIANT_SOURCES:
        st.markdown(f"- [{label}]({url})")

    risk = result.get("risk_indicators") or result.get("epidemiological_risk")
    if risk:
        st.markdown("### Backend-supplied epidemiological context")
        st.warning("These indicators are not a prediction of a future pandemic. Interpret them using their documented method, data, validation, and uncertainty.")
        st.json(risk) if isinstance(risk, dict) else st.write(risk)
    else:
        st.caption("No epidemiological risk indicator was supplied. A single genome does not predict an outbreak.")

    generated_at = datetime.now().isoformat(timespec="seconds")
    report = {
        "project": "VIGESORA",
        "generated_at": generated_at,
        "filename": result.get("filename"),
        "demo_mode": result.get("demo_mode", False),
        "confidence_display": confidence_label,
        "result": result,
        "variant_information": info,
        "prevention_guidance": PREVENTION_GUIDANCE,
        "treatment_guidance": TREATMENT_GUIDANCE,
        "trusted_references": [{"title": label, "url": url} for label, url in VARIANT_SOURCES],
        "limitations": "Experimental classification among supported classes only; not a formal lineage assignment, clinical diagnosis, or outbreak prediction.",
    }
    timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
    st.markdown("### Download and print reports")
    st.caption("Reports are generated from this analysis result. Use your browser or PDF viewer's print command after opening the PDF.")
    cjson, cpdf = st.columns(2)
    with cjson:
        st.download_button(
            "Download JSON report",
            data=json.dumps(report, indent=2, ensure_ascii=False, default=str),
            file_name=f"vigesora_report_{timestamp}.json",
            mime="application/json",
            type="primary",
            on_click=add_activity,
            args=(f"JSON report exported: {result.get('filename', 'sequence')}",),
        )
    with cpdf:
        if REPORTLAB_AVAILABLE:
            pdf_bytes = build_pdf_report(report)
            st.download_button(
                "Download printable PDF",
                data=pdf_bytes,
                file_name=f"vigesora_report_{timestamp}.pdf",
                mime="application/pdf",
                type="primary",
                on_click=add_activity,
                args=(f"PDF report exported: {result.get('filename', 'sequence')}",),
            )
        else:
            st.warning("PDF export needs ReportLab. Install it with: python -m pip install reportlab")

    if st.button("Save to Previous Analyses", key="save_analysis"):
        st.session_state.analyses.insert(0, {
            "Analysis name": result.get("filename", "Uploaded sequence"),
            "Date": datetime.now().strftime("%d %b %Y"),
            "Predicted variant": str(variant),
            "Model score": confidence_label,
            "Mode": "Demo" if result.get("demo_mode") else "API",
        })
        add_activity(f"Saved analysis record: {result.get('filename', 'Uploaded sequence')}")
        st.success("Saved in this session. Persistent database storage is not connected yet.")
    c1, c2 = st.columns(2)
    with c1:
        if st.button("Analyze another genome", type="secondary", **STRETCH):
            navigate("New Analysis")
    with c2:
        if st.button("Back to Research Overview", **STRETCH):
            navigate("Research Overview")


